const $=id=>document.getElementById(id),$$=s=>[...document.querySelectorAll(s)];
/* ---------- Core: works even where the URL hash or localStorage is blocked (previews, sandboxed frames) ---------- */
let CUR=(location.hash||'').slice(1)||'/';
const IN_FRAME=(function(){try{return window.self!==window.top}catch(e){return true}})();
function go(to){CUR=to;if(!IN_FRAME){try{if(location.hash.slice(1)!==to)location.hash=to}catch(e){}}route()}
function redirect(to){CUR=to;if(!IN_FRAME){try{location.replace('#'+to)}catch(e){}}route()}
addEventListener('hashchange',()=>{const h=location.hash.slice(1)||'/';if(h!==CUR){CUR=h;route()}});
document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('a[href^="#/"]');if(!a)return;e.preventDefault();
  if(a.hasAttribute('data-login')&&getSession()){logout();return}go(a.getAttribute('href').slice(1))});
function wire(form,fn){const run=e=>{if(e)e.preventDefault();fn()};form.addEventListener('submit',run);
  form.querySelectorAll('[data-submit]').forEach(b=>b.addEventListener('click',run));
  form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName!=='TEXTAREA')run(e)})}
const MEM={},store={
  get:k=>{try{const v=localStorage.getItem(k);if(v!==null)return v}catch(e){}return MEM[k]===undefined?null:MEM[k]},
  set:(k,v)=>{MEM[k]=v;try{localStorage.setItem(k,v)}catch(e){}},
  del:k=>{delete MEM[k];try{localStorage.removeItem(k)}catch(e){}}};
const ICONS=DATA.icons,SERVICES=DATA.services,PROJECTS=DATA.projects;
const icon=k=>'<svg viewBox="0 0 24 24">'+ICONS[k]+'</svg>';
let gid=0;
const thumb=p=>{const i='g'+(++gid);if(PRJPICS[p.slug])return '<svg class="thumb" viewBox="0 0 320 200" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Sample screens from '+p.title+'"><defs><linearGradient id="'+i+'" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="'+p.c1+'"/><stop offset="1" stop-color="'+p.c2+'"/></linearGradient></defs><rect width="320" height="200" fill="url(#'+i+')"/>'+PRJPICS[p.slug]+'</svg>';return '<svg class="thumb" viewBox="0 0 320 200" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="'+i+'" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="'+p.c1+'"/><stop offset="1" stop-color="'+p.c2+'"/></linearGradient></defs><rect width="320" height="200" fill="url(#'+i+')"/>'+DATA.shapes[p.cat]+'</svg>'};
const sCard=s=>'<li><a class="service-card" href="#/services/'+s.slug+'"><div class="icon-box" aria-hidden="true">'+icon(s.icon)+'</div><h3>'+s.title+'</h3><p>'+s.short+'</p><span class="more">Learn more</span></a></li>';
const pCard=p=>'<li><a class="service-card project-card" href="#/projects/'+p.slug+'">'+thumb(p)+'<p class="kind">'+p.kindLabel+'</p><h3>'+p.title+'</h3><p>'+p.short+'</p><p class="ex"><b>Example:</b> '+(PRJEX[p.slug]||'')+'</p><ul class="tags">'+p.tags.map(t=>'<li class="tag">'+t+'</li>').join('')+'</ul></a></li>';
