/* ---------- Session (DEMO AUTH: stored in this browser only; replace with server-side auth) ---------- */
const getSession=()=>{try{return JSON.parse(store.get('tp_session'))}catch(e){return null}};
const USERS='tp_users',getUsers=()=>{try{return JSON.parse(store.get(USERS))||{}}catch(e){return {}}};
async function hash(s){if(window.crypto&&crypto.subtle){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}return btoa(unescape(encodeURIComponent(s)))}
function applySession(){let s=getSession();if(s&&!(s.name||'').trim())s=saveSession({name:nameFromEmail(s.email)});
  document.body.classList.toggle('authed',!!s);if(s)paintProfile(s);return s}
/* Shared storage keys: the admin dashboard (../admin/admin.html) reads these same keys. */
const ADMIN_EMAIL='techpulse.admin@gmail.com',ADMIN_PW='TechPulse@2026',MSGS='tp_messages',ACT='tp_activity',ADM_SES='tp_admin_session',ADMIN_URL='../admin/admin.html';
const rdJ=(k,d)=>{try{const v=JSON.parse(store.get(k));return v==null?d:v}catch(e){return d}};
const nameFromEmail=e=>String(e||'').split('@')[0].replace(/[._-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase()).trim()||'Client';
function logAct(type,detail,user){const a=rdJ(ACT,[]);a.push({id:Date.now()+Math.random().toString(36).slice(2,6),t:Date.now(),type,user:user||(getSession()||{}).email||'Visitor',detail});store.set(ACT,JSON.stringify(a.slice(-1000)))}
/* Make sure the admin account exists in the same user list every other account lives in. */
async function ensureAdmin(){const us=getUsers();if(us[ADMIN_EMAIL]&&us[ADMIN_EMAIL].role==='admin')return;
  us[ADMIN_EMAIL]=Object.assign({},us[ADMIN_EMAIL]||{},{name:'TechPulse Admin',email:ADMIN_EMAIL,hash:await hash(ADMIN_PW),role:'admin',status:'active',createdAt:Date.now(),lastLogin:null});
  store.set(USERS,JSON.stringify(us))}
ensureAdmin();
function logout(){const s=getSession();if(s)logAct('logout','Logged out',s.email);store.del('tp_session');store.del(ADM_SES);go('/')}
$('logout').onclick=logout;


