/* ---------- Router ---------- */
const ROUTES=[['/','home'],['/about','about'],['/services','services'],['/services/:id','service'],['/projects','projects'],['/projects/:id','project'],['/platform','platform'],['/contact','contact'],['/login','login'],['/forgot','forgot'],['/dashboard','dashboard'],['/profile','profile']];
const TITLES={home:'Turning Ideas into Digital Solutions',about:'About Us',services:'Services',projects:'Projects',platform:'Computing Platform',contact:'Contact Us',login:'Login / Sign Up',forgot:'Forgot Password',dashboard:'Dashboard',profile:'Your Profile','404':'Page not found'};
const NAVKEY={service:'services',project:'projects'};
function parse(){const h=CUR||'/',[p,qs]=h.split('?');return{path:p.replace(/\/+$/,'')||'/',q:new URLSearchParams(qs||'')}}
function match(path){for(const [p,name] of ROUTES){const a=p.split('/'),b=path.split('/');if(a.length!==b.length)continue;const params={};let ok=true;
  a.forEach((s,i)=>{if(s[0]===':')params[s.slice(1)]=decodeURIComponent(b[i]);else if(s!==b[i])ok=false});if(ok)return{name,params}}return{name:'404',params:{}}}
function route(){
  const {path,q}=parse();let {name,params}=match(path),title=null;const sess=applySession();
  document.body.classList.toggle('login-screen',name==='login'||name==='forgot');
  /* LOGIN GATE: nothing but the login page is reachable until the visitor signs in */
  if(!sess&&name!=='login'&&name!=='forgot'){redirect('/login'+(path&&path!=='/'?'?next='+encodeURIComponent(path):''));return}
  /* Keep the login page as the initial screen, even if a previous demo session exists. */
  if(sess&&name==='login'&&q.get('next')){const nx=q.get('next');if(nx&&nx[0]==='/'&&nx.indexOf('/login')!==0){/* continue to requested page only after a deliberate login flow */}}
  if(name==='service'){const s=SERVICES.find(x=>x.slug===params.id);if(s){showService(s);title=s.title}else name='404'}
  if(name==='project'){const p=PROJECTS.find(x=>x.slug===params.id);if(p){showProject(p);title=p.title}else name='404'}
  $$('.view').forEach(v=>v.hidden=v.dataset.route!==name);
  const key=NAVKEY[name]||name;$$('[data-nav]').forEach(a=>a.dataset.nav===key?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));
  document.title=(title||TITLES[name])+' | TechPulse Innovations';
  window.scrollTo(0,0);$('navLinks').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');
  if(name==='contact')prefill(q);if(name==='login')setTab(q.get('tab')==='signup'?'signup':'login');if(name==='forgot')resetForgot();if(name==='dashboard')renderDash(sess);if(name==='profile')renderProfile(sess);closeMenu();
  $('app').focus({preventScroll:true});
}
const toggle=$('menuToggle');toggle.addEventListener('click',()=>{const o=$('navLinks').classList.toggle('open');toggle.setAttribute('aria-expanded',o)});

/* ---------- Contact ---------- */
const f=$('contactForm'),st=$('status'),emailOk=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
const rules={name:v=>v.trim().length>=2||'Enter your name.',email:v=>emailOk(v)||'Enter a valid email address.',message:v=>v.trim().length>=10||'Message must be at least 10 characters.'};
function prefill(q){const s=getSession();if(s){if(!f.elements.name.value)f.elements.name.value=s.name||'';if(!f.elements.email.value)f.elements.email.value=s.email||''}
  if(q.get('service'))f.elements.topic.value=q.get('service');if(q.get('msg'))f.elements.message.value=q.get('msg');st.textContent=''}
wire(f,()=>{let ok=true;
  for(const k in rules){const r=rules[k](f.elements[k].value);$('e-'+k).textContent=r===true?'':r;if(r!==true)ok=false}
  if(!ok){st.className='status bad';st.textContent='Please fix the highlighted fields.';return}
  /* Saved to the shared inbox that the admin dashboard reads. */
  const n=f.elements.name.value.trim(),em=f.elements.email.value.trim().toLowerCase(),t=f.elements.topic.selectedOptions[0].textContent,msg=f.elements.message.value.trim(),ses=getSession();
  const ms=rdJ(MSGS,[]);ms.push({id:Date.now()+Math.random().toString(36).slice(2,6),name:n,email:em,topic:t,text:msg,t:Date.now(),read:false,starred:false,replied:false,userEmail:ses?ses.email:em});store.set(MSGS,JSON.stringify(ms));
  logAct('request',f.elements.topic.value?'Requested '+t:'Sent a message',ses?ses.email:em);
  f.elements.message.value='';st.className='status ok';st.textContent='Thank you, '+n.split(' ')[0]+'. Your message has been sent. We will get back to you within two business days.';});

/* ---------- Login / Sign Up ---------- */
function setTab(w){['login','signup'].forEach(n=>{$('panel-'+n).hidden=n!==w;$('tab-'+n).setAttribute('aria-selected',n===w)})}
$('tab-login').onclick=()=>setTab('login');$('tab-signup').onclick=()=>setTab('signup');
$$('.pw-toggle').forEach(b=>b.onclick=()=>{const i=$(b.dataset.for),s=i.type==='password';i.type=s?'text':'password';b.textContent=s?'Hide':'Show'});
const err=(id,m)=>{$('e-'+id).textContent=m||''};
function enter(u){try{store.set('tp_last',u.email)}catch(e){}store.set('tp_session',JSON.stringify({name:(u.name||'').trim()||nameFromEmail(u.email),email:u.email,role:u.role||'client'}));
  if(u.role==='admin'){store.set(ADM_SES,JSON.stringify({email:u.email,name:(u.name||'').trim()||'Admin',t:Date.now()}));logAct('admin','Admin signed in',u.email);location.href=ADMIN_URL;return}
  store.del(ADM_SES);const nx=parse().q.get('next');go(nx&&nx[0]==='/'&&nx.indexOf('/login')!==0?nx:'/')}
