/* ---------- Forgot password page (demo: accounts live in this browser) ---------- */
function resetForgot(){['fp-pw','fp-pw2'].forEach(id=>{$(id).value='';$(id).type='password'});['e-fp-pw','e-fp-pw2'].forEach(id=>$(id).textContent='');
  document.querySelectorAll('#fp-step2 .pw-toggle').forEach(b=>b.textContent='Show');
  const st=$('s-forgot');st.className='status';st.textContent='';
  const e=$('l-email').value.trim().toLowerCase();if(emailOk(e)){/* keep what was typed on the login page */}}
/* Which account gets the new password: the email typed on the login page, else the last account used in this browser, else the only account. */
function resetTarget(){const us=getUsers(),typed=($('l-email').value||'').trim().toLowerCase();
  if(typed&&us[typed])return typed;const last=store.get('tp_last');if(last&&us[last])return last;
  const keys=Object.keys(us);return keys.length===1?keys[0]:null}
wire($('fp-step2'),async()=>{const pw=$('fp-pw').value,p2=$('fp-pw2').value,st=$('s-forgot');st.textContent='';
  err('fp-pw',pw.length>=8?'':'Use at least 8 characters.');err('fp-pw2',pw===p2?'':'Passwords do not match.');
  if(pw.length<8||pw!==p2)return;
  const em=resetTarget();if(!em){st.className='status bad';st.textContent='No saved account found in this browser. Type your email on the login page first, or sign up.';return}
  const us=getUsers();us[em].hash=await hash(pw);store.set(USERS,JSON.stringify(us));
  st.className='status ok';st.textContent='Password updated. Taking you back to login...';
  setTimeout(()=>{$('l-email').value=em;$('l-pw').value='';go('/login')},1500)});
wire($('panel-login'),async()=>{const em=$('l-email').value.trim().toLowerCase(),pw=$('l-pw').value,s=$('s-login');
  err('l-email',emailOk(em)?'':'Enter a valid email address.');err('l-pw',pw?'':'Enter your password.');if(!emailOk(em)||!pw)return;
  const us=getUsers();let u=us[em];
  if(!u||u.hash!==await hash(pw)){logAct('failed','Wrong email or password',em);s.className='status bad';s.textContent='Email or password is incorrect.';return}
  if(u.status==='suspended'){s.className='status bad';s.textContent='This account is suspended. Contact an administrator.';return}
  if(!u.role){u.role='client';us[em]=u;store.set(USERS,JSON.stringify(us))}
  u.lastLogin=Date.now();us[em]=u;store.set(USERS,JSON.stringify(us));if(u.role!=='admin')logAct('login','Logged in',em);enter(u)});
wire($('panel-signup'),async()=>{const n=$('s-name').value.trim(),em=$('s-email').value.trim().toLowerCase(),pw=$('s-pw').value,p2=$('s-pw2').value,s=$('s-signup');
  err('s-name',n.length>=2?'':'Enter your full name.');err('s-email',emailOk(em)?'':'Enter a valid email address.');err('s-pw',pw.length>=8?'':'Use at least 8 characters.');err('s-pw2',pw===p2?'':'Passwords do not match.');
  if(n.length<2||!emailOk(em)||pw.length<8||pw!==p2)return;
  const us=getUsers();if(us[em]){s.className='status bad';s.textContent='An account with this email already exists. Try logging in.';return}
  us[em]={name:n,email:em,hash:await hash(pw),role:'client',status:'active',createdAt:Date.now(),lastLogin:Date.now()};store.set(USERS,JSON.stringify(us));logAct('signup','Created an account',em);enter(us[em])});


