function renderDash(s){$('hello').textContent='Welcome, '+(s.name||'there').split(' ')[0];$('who').textContent='Signed in as '+s.email+'. Track your projects and share files with the TechPulse team.';
  $('projectsList').innerHTML=PR.map(p=>'<div class="proj-row"><div class="top"><span>'+p[0]+'</span><small>'+p[1]+' &middot; '+p[2]+'%</small></div><div class="progress" role="progressbar" aria-label="'+p[0]+' progress" aria-valuenow="'+p[2]+'" aria-valuemin="0" aria-valuemax="100"><span style="width:'+p[2]+'%"></span></div></div>').join('');
  $('st1').textContent=PR.length;$('st2').textContent=Math.round(PR.reduce((a,p)=>a+p[2],0)/PR.length)+'%';$('st3').textContent=fileCount}
function addFiles(fs){[...fs].forEach(x=>{const li=document.createElement('li'),a=document.createElement('span'),b=document.createElement('span');a.textContent=x.name;b.textContent=(x.size/1024).toFixed(1)+' KB';li.append(a,b);$('fileList').append(li);fileCount++;logAct('file','Shared '+x.name)});$('st3').textContent=fileCount}
$('files').onchange=e=>addFiles(e.target.files);
const dz=$('drop');['dragover','dragenter'].forEach(t=>dz.addEventListener(t,e=>{e.preventDefault();dz.classList.add('drag')}));
['dragleave','drop'].forEach(t=>dz.addEventListener(t,e=>{e.preventDefault();dz.classList.remove('drag')}));dz.addEventListener('drop',e=>addFiles(e.dataTransfer.files));
